,\n  errorMessage: props.errorMessage,\n  classes: cls,\n  rows: props.rows,\n  autocomplete: props.autocomplete,\n  spellcheck: props.spellcheck,\n  value: props.value\n}) }}','active','2025-08-24 16:24:26','2025-08-26 13:49:49',0,'null'),(33,'checkbox',1,'checkbox','Checkboxes','A group of checkboxes allowing users to select zero, one, or multiple options.','{\"hint\": {\"text\": {\"en\": \"Select all that apply.\", \"fr\": \"Sélectionnez toutes les options applicables.\"}}, \"name\": \"example-checkboxes\", \"items\": [{\"text\": \"Option A\", \"value\": \"a\"}, {\"text\": \"Option B\", \"value\": \"b\"}, {\"text\": \"Option C\", \"value\": \"c\"}], \"classes\": \"govuk-checkboxes\", \"disabled\": false, \"fieldset\": {\"legend\": {\"text\": \"Select all that apply\", \"classes\": \"govuk-fieldset__legend--l\", \"isPageHeading\": false}}, \"formGroup\": {\"classes\": \"\"}}','[{\"key\": \"legendText\", \"path\": \"fieldset.legend.text\", \"type\": \"text\", \"label\": \"Legend Text\"}, {\"key\": \"hintText\", \"path\": \"hint.text\", \"type\": \"text\", \"label\": \"Hint Text\"}, {\"key\": \"legendClasses\", \"path\": \"fieldset.legend.classes\", \"type\": \"select\", \"label\": \"Legend Classes\", \"options\": [{\"label\": \"Small (s)\", \"value\": \"govuk-fieldset__legend--s\"}, {\"label\": \"Medium (m)\", \"value\": \"govuk-fieldset__legend--m\"}, {\"label\": \"Large (l) (default)\", \"value\": \"govuk-fieldset__legend--l\"}, {\"label\": \"Extra Large (xl)\", \"value\": \"govuk-fieldset__legend--xl\"}, {\"label\": \"None (no size modifier)\", \"value\": \"\"}]}, {\"key\": \"isPageHeading\", \"path\": \"fieldset.legend.isPageHeading\", \"type\": \"select\", \"label\": \"Is Page Heading?\", \"options\": [{\"label\": \"True\", \"value\": true}, {\"label\": \"False\", \"value\": false}]}, {\"key\": \"name\", \"path\": \"name\", \"type\": \"text\", \"label\": \"Data Key\"}, {\"key\": \"classes\", \"path\": \"classes\", \"type\": \"select\", \"label\": \"Container Classes\", \"options\": [{\"label\": \"Default\", \"value\": \"govuk-checkboxes\"}, {\"label\": \"Small\", \"value\": \"govuk-checkboxes govuk-checkboxes--small\"}]}, {\"key\": \"formGroup.classes\", \"path\": \"formGroup.classes\", \"type\": \"select\", \"label\": \"Form Group Classes\", \"options\": [{\"label\": \"Default (none)\", \"value\": \"\"}, {\"label\": \"Error State\", \"value\": \"govuk-form-group--error\"}]}, {\"key\": \"disabled\", \"path\": \"disabled\", \"type\": \"select\", \"label\": \"Disabled?\", \"options\": [{\"label\": \"True\", \"value\": true}, {\"label\": \"False\", \"value\": false}]}, {\"key\": \"options\", \"path\": \"items\", \"type\": \"optionList\", \"label\": \"Options\"}]','{% from \"govuk/components/checkboxes/macro.njk\" import govukCheckboxes %}\n{% set cls = props.classes or \'govuk-checkboxes\' %}\n{% if \'govuk-checkboxes\' not in cls %}{% set cls = \'govuk-checkboxes \' + cls %}{% endif %}\n{{ govukCheckboxes({\n  name: props.name,\n  fieldset: {\n    legend: {\n      text: props.fieldset.legend.text,\n      isPageHeading: props.fieldset.legend.isPageHeading,\n      classes: props.fieldset.legend.classes\n    }\n  },\n  hint: props.hint,\n  classes: cls,\n  formGroup: { classes: props.formGroup.classes },\n  disabled: props.disabled,\n  items: props.items\n}) }}','active','2025-08-25 10:57:47','2025-08-25 10:57:47',1,'[\"text\", \"value\", \"hint\"]'),(35,'signature-ack',1,'signature-ack','Signature Acknowledgment','Captures an attested typed name that is explicitly locked by clicking a Sign action; stores { signed: true, name } object.','{\"id\": \"\", \"hint\": {\"text\": \"Enter your full legal name then press Sign.\"}, \"name\": \"legal_submission_sig\", \"label\": {\"text\": \"Type your full name to sign\", \"classes\": \"govuk-label--m\"}, \"required\": true, \"formGroup\": {\"classes\": \"\"}, \"boxPadding\": \"m\", \"clearLabel\": {\"text\": \"Clear\"}, \"actionLabel\": {\"text\": \"Sign Now\"}, \"placeholder\": {\"text\": \"First Last\"}, \"handwritingFont\": \"cursive\", \"statusSignedText\": {\"text\": \"Signed\"}, \"statusUnsignedText\": {\"text\": \"Not signed\"}}','[{\"key\": \"name\", \"path\": \"name\", \"type\": \"text\", \"label\": \"Data Key\"}, {\"key\": \"label.text\", \"path\": \"label.text\", \"type\": \"text\", \"label\": \"Label Text\"}, {\"key\": \"label.classes\", \"path\": \"label.classes\", \"type\": \"select\", \"label\": \"Label Classes\", \"options\": [{\"label\": \"Default (none)\", \"value\": \"\"}, {\"label\": \"Small (s)\", \"value\": \"govuk-label--s\"}, {\"label\": \"Medium (m)\", \"value\": \"govuk-label--m\"}, {\"label\": \"Large (l)\", \"value\": \"govuk-label--l\"}, {\"label\": \"Extra Large (xl)\", \"value\": \"govuk-label--xl\"}, {\"label\": \"Visually Hidden\", \"value\": \"govuk-visually-hidden\"}]}, {\"key\": \"hint.text\", \"path\": \"hint.text\", \"type\": \"text\", \"label\": \"Hint Text\"}, {\"key\": \"actionLabel.text\", \"path\": \"actionLabel.text\", \"type\": \"text\", \"label\": \"Sign Button Label\"}, {\"key\": \"clearLabel.text\", \"path\": \"clearLabel.text\", \"type\": \"text\", \"label\": \"Clear Button Label\"}, {\"key\": \"placeholder.text\", \"path\": \"placeholder.text\", \"type\": \"text\", \"label\": \"Placeholder Text\"}, {\"key\": \"statusSignedText.text\", \"path\": \"statusSignedText.text\", \"type\": \"text\", \"label\": \"Signed Status Text\"}, {\"key\": \"statusUnsignedText.text\", \"path\": \"statusUnsignedText.text\", \"type\": \"text\", \"label\": \"Unsigned Status Text\"}, {\"key\": \"handwritingFont\", \"path\": \"handwritingFont\", \"type\": \"text\", \"label\": \"Handwriting Font\"}, {\"key\": \"required\", \"path\": \"required\", \"type\": \"select\", \"label\": \"Required?\", \"options\": [{\"label\": \"Yes\", \"value\": true}, {\"label\": \"No\", \"value\": false}]}, {\"key\": \"boxPadding\", \"path\": \"boxPadding\", \"type\": \"select\", \"label\": \"Box Padding\", \"options\": [{\"label\": \"Small\", \"value\": \"s\"}, {\"label\": \"Medium\", \"value\": \"m\"}, {\"label\": \"Large\", \"value\": \"l\"}, {\"label\": \"Extra Large\", \"value\": \"xl\"}]}, {\"key\": \"formGroup.classes\", \"path\": \"formGroup.classes\", \"type\": \"select\", \"label\": \"Form Group Classes\", \"options\": [{\"label\": \"Default (none)\", \"value\": \"\"}, {\"label\": \"Error State\", \"value\": \"govuk-form-group--error\"}]}]','{% set paddingScale = { \'s\': { \'y\': \'0.35rem\', \'x\': \'1.25rem\' }, \'m\': { \'y\': \'1.35rem\', \'x\': \'1.85rem\' }, \'l\': { \'y\': \'2.35rem\', \'x\': \'2.45rem\' }, \'xl\': { \'y\': \'3.35rem\', \'x\': \'3.05rem\' } } %}\n{% set padKey = props.boxPadding or \'m\' %}\n{% set pad = paddingScale[padKey] or paddingScale[\'m\'] %}\n{% set padY = pad.y %}\n{% set padX = pad.x %}\n{% set labelText = props.label and (props.label.text or props.label.en or props.label.fr) %}\n{% set labelClass = props.label and props.label.classes %}\n{% set hintText = props.hint and (props.hint.text or props.hint.en or props.hint.fr) %}\n{% set placeholder = props.placeholder and (props.placeholder.text or props.placeholder.en or props.placeholder.fr) %}\n{% set actionLabel = props.actionLabel and (props.actionLabel.text or props.actionLabel.en or props.actionLabel.fr) or \'Sign\' %}\n{% set clearLabel = props.clearLabel and (props.clearLabel.text or props.clearLabel.en or props.clearLabel.fr) or \'Clear\' %}\n{% set statusSigned = props.statusSignedText and (props.statusSignedText.text or props.statusSignedText.en or props.statusSignedText.fr) or props.statusSignedText or \'Signed\' %}\n{% set statusUnsigned = props.statusUnsignedText and (props.statusUnsignedText.text or props.statusUnsignedText.en or props.statusUnsignedText.fr) or props.statusUnsignedText or \'Not signed\' %}\n<div class=\"app-signature-ack\">\n  {% if labelText %}<label class=\"govuk-label{{ labelClass and (\' \' + labelClass) or \'\' }}\" for=\"{{ props.id or props.name }}\">{{ labelText }}</label>{% endif %}\n  {% if hintText %}<div class=\"govuk-hint\">{{ hintText }}</div>{% endif %}\n  <div class=\"signature-ack__row\" style=\"display:flex;align-items:center;gap:12px;flex-wrap:wrap;\">\n    <div class=\"signature-ack__input-wrapper\" style=\"flex:0 0 33%;min-width:260px;max-width:420px;\">\n      <input class=\"govuk-input signature-ack__input\" id=\"{{ props.id or props.name }}\" name=\"{{ props.name }}\" type=\"text\" value=\"{{ props.value or \'\' }}\"{% if placeholder %} placeholder=\"{{ placeholder }}\"{% endif %}{% if props.required %} aria-required=\"true\" required{% endif %} style=\"padding: {{ padY }} {{ padX }}; text-align:center; min-height: calc({{ padY }} * 2 + 1.25rem); width:100%;\" data-component=\"signature-ack\" />\n    </div>\n    <div class=\"signature-ack__actions\" style=\"display:flex;gap:8px;align-items:center;\">\n      <button type=\"button\" class=\"govuk-button\">{{ actionLabel }}</button>\n      <button type=\"button\" class=\"govuk-button govuk-button--warning\">{{ clearLabel }}</button>\n    </div>\n    <div class=\"signature-ack__status govuk-hint\" data-signature-status style=\"flex-basis:100%;margin-top:4px;\">{% if props.value %}{{ statusSigned }}{% else %}{{ statusUnsigned }}{% endif %}</div>\n  </div>\n</div>','active','2025-09-16 13:18:24','2025-12-07 08:18:47',0,'null');
