DROP TABLE IF EXISTS `iset_regional_snapshot_report`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `iset_regional_snapshot_report` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `region_id` tinyint unsigned NOT NULL,
  `period_type` enum('month','quarter','year') COLLATE utf8mb4_unicode_ci NOT NULL,
  `period_start` date NOT NULL,
  `period_end` date NOT NULL,
  `snapshot_status` enum('draft','final') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `regional_manager_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `regional_coordinator_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `coordinator_salary_amount` decimal(14,2) DEFAULT NULL,
  `operating_costs_amount` decimal(14,2) DEFAULT NULL,
  `compliance_flag` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `comments_recommendations` text COLLATE utf8mb4_unicode_ci,
  `manual_inputs_json` json DEFAULT NULL,
  `created_by_staff_profile_id` bigint unsigned DEFAULT NULL,
  `updated_by_staff_profile_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_snapshot_region_period` (`region_id`,`period_type`,`period_start`,`period_end`),
  KEY `idx_snapshot_period` (`period_type`,`period_start`,`period_end`),
  KEY `idx_snapshot_status` (`snapshot_status`),
  KEY `idx_snapshot_created_by` (`created_by_staff_profile_id`),
  KEY `idx_snapshot_updated_by` (`updated_by_staff_profile_id`),
  CONSTRAINT `fk_snapshot_created_by` FOREIGN KEY (`created_by_staff_profile_id`) REFERENCES `staff_profiles` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_snapshot_region` FOREIGN KEY (`region_id`) REFERENCES `canada_region` (`region_id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_snapshot_updated_by` FOREIGN KEY (`updated_by_staff_profile_id`) REFERENCES `staff_profiles` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
