INSERT INTO `notification_template` VALUES (1,'Submission confirmation email','Email','Released','en','Your application has been submitted','Dear {applicant_name}\n\nThank you for submitting your application to the Indigenous Skills and Employment Training (ISET) Program. We received it on {submission_date}.\n\n[b]Reference:[/b] {application_id}\n\nWhat happens next:\n[ul]\n[li]Our team will review your application and contact you if we need more information[/li]\n[li]You can log in anytime to check the status of your file, upload documents, or send secure messages to your case manager.[/li]\n[/ul]If you have any questions, please send us a secure message through your account so we can respond promptly.\n\nYour ISET team at NWAC','{\"en\": {\"subject\": \"Your application has been submitted\", \"textBody\": \"Dear {applicant_name}\\n\\nThank you for submitting your application to the Indigenous Skills and Employment Training (ISET) Program. We received it on {submission_date}.\\n\\n[b]Reference:[/b] {application_id}\\n\\nWhat happens next:\\n[ul]\\n[li]Our team will review your application and contact you if we need more information[/li]\\n[li]You can log in anytime to check the status of your file, upload documents, or send secure messages to your case manager.[/li]\\n[/ul]If you have any questions, please send us a secure message through your account so we can respond promptly.\\n\\nYour ISET team at NWAC\"}, \"fr\": {\"subject\": \"Votre demande a été soumise\", \"textBody\": \"Cher {applicant_name},\\n\\nMerci d\'avoir soumis votre demande au Programme de formation en compétences et emploi autochtones (ISET). Nous l\'avons reçue le {submission_date}.\\n\\n[b]Référence :[/b] {application_id}\\n\\nCe qui se passe ensuite :\\n[ul]\\n[li]Notre équipe examinera votre demande et vous contactera si nous avons besoin de plus d\'informations[/li]\\n[li]Vous pouvez vous connecter à votre compte candidat en tout temps pour vérifier l\'état de votre dossier, télécharger des documents ou envoyer des messages sécurisés à vos intervenants.[/li]\\n[/ul]Si vous avez des questions, veuillez nous envoyer un message sécurisé via votre compte afin que nous puissions répondre rapidement.\\n\\nVotre équipe ISET chez NWAC\"}}','2025-06-16 12:01:17','2026-02-17 13:27:57'),(8,'\"You\'ve got secure mail\" email','Email','Draft','en','ISET - New Message','Dear {message_to_name}\n\nYour ISET caseworking team has sent you a new message.\n\n[b]Subject:[/b] {message_subject}\n\n[link url=\"https://nwac-public-test.awentech.ca/\"]Please sign in here to read your messages[/link]\n\nRegards\n\n{message_from_name}\n\n\n','{\"en\": {\"subject\": \"ISET - New Message\", \"textBody\": \"Dear {message_to_name}\\n\\nYour ISET caseworking team has sent you a new message.\\n\\n[b]Subject:[/b] {message_subject}\\n\\n[link url=\\\"https://nwac-public-test.awentech.ca/\\\"]Please sign in here to read your messages[/link]\\n\\nRegards\\n\\n{message_from_name}\\n\\n\\n\"}, \"fr\": {\"subject\": \"ISET - Nouveau message\", \"textBody\": \"Bonjour {message_to_name}\\n\\nVotre équipe de gestion de cas d’ISET vous a envoyé un nouveau message.\\n\\n[b]Objet :[/b] {message_subject}\\n\\n[link url=\\\"https://nwac-public-test.awentech.ca/\\\"]Veuillez ouvrir une session ici pour lire vos messages[/link]\\n\\nSalutations\\n\\n{message_from_name}\\n\\n\\n\"}}','2025-11-13 11:22:21','2026-01-16 11:05:27'),(10,'Document reminder','Email','Draft','en','Reminder - ISET Documents Requested','Dear {applicant_name},\n\nWe’re still waiting for the documents we requested to continue reviewing your ISET application.\n\n[b]Reference:[/b] {tracking_id}\n\nWhat you can do now:\n[ul]\n[li]Sign in to upload the requested documents[/li]\n[li]Send us a secure message if you need help or more time[/li]\n[li]If you already submitted the documents, you can ignore this reminder[/li]\n[/ul]\n\n[link url=\"{portal_dashboard_url}\"]Sign in here to upload documents[/link]\n\nIf you need assistance, please contact your case manager\n\nYour ISET Team at NWAC\n','{\"en\": {\"subject\": \"Reminder - ISET Documents Requested\", \"textBody\": \"Dear {applicant_name},\\n\\nWe’re still waiting for the documents we requested to continue reviewing your ISET application.\\n\\n[b]Reference:[/b] {tracking_id}\\n\\nWhat you can do now:\\n[ul]\\n[li]Sign in to upload the requested documents[/li]\\n[li]Send us a secure message if you need help or more time[/li]\\n[li]If you already submitted the documents, you can ignore this reminder[/li]\\n[/ul]\\n\\n[link url=\\\"{portal_dashboard_url}\\\"]Sign in here to upload documents[/link]\\n\\nIf you need assistance, please contact your case manager\\n\\nYour ISET Team at NWAC\\n\"}, \"fr\": {\"subject\": \"Rappel - Documents ISET demandés\", \"textBody\": \"Cher {applicant_name},\\n\\nNous attendons toujours les documents que nous avons demandés pour continuer à examiner votre demande ISET.\\n\\n[b]Référence :[/b] {tracking_id}\\n\\nCe que vous pouvez faire maintenant :\\n[ul]\\n[li]Connectez-vous pour télécharger les documents demandés[/li]\\n[li]Envoyez-nous un message sécurisé si vous avez besoin d’aide ou de plus de temps[/li]\\n[li]Si vous avez déjà soumis les documents, vous pouvez ignorer ce rappel[/li]\\n[/ul]\\n\\n[link url=\\\"{portal_dashboard_url}\\\"]Connectez-vous ici pour télécharger les documents[/link]\\n\\nSi vous avez besoin d’aide, contactez-nous à {support_email}.\\n\\nVotre équipe ISET chez NWAC\\n\"}}','2026-01-16 12:31:25','2026-01-16 12:33:26'),(11,'Closure warning','Email','Draft','en','ISET - Final Reminder','Dear {applicant_name},\n\nWe still haven’t received the documents needed to continue your ISET application. To keep your file open, please submit the outstanding documents as soon as possible.\n\n[b]Reference:[/b] {tracking_id}\n\nIf you need more time or are having trouble uploading files, please send us a secure message and we’ll help.\n\n[link url=\"{portal_dashboard_url}\"]Sign in here to upload documents or send a message[/link]\n\nIf we don’t hear from you, your file may be closed.\n\nYour ISET Team at NWAC\n','{\"en\": {\"subject\": \"ISET - Final Reminder\", \"textBody\": \"Dear {applicant_name},\\n\\nWe still haven’t received the documents needed to continue your ISET application. To keep your file open, please submit the outstanding documents as soon as possible.\\n\\n[b]Reference:[/b] {tracking_id}\\n\\nIf you need more time or are having trouble uploading files, please send us a secure message and we’ll help.\\n\\n[link url=\\\"{portal_dashboard_url}\\\"]Sign in here to upload documents or send a message[/link]\\n\\nIf we don’t hear from you, your file may be closed.\\n\\nYour ISET Team at NWAC\\n\"}, \"fr\": {\"subject\": \"ISET - Dernier rappel\", \"textBody\": \"Cher {applicant_name},\\n\\nNous n’avons toujours pas reçu les documents nécessaires pour poursuivre votre demande ISET. Pour garder votre dossier ouvert, veuillez soumettre les documents manquants dès que possible.\\n\\n[b]Référence :[/b] {tracking_id}\\n\\nSi vous avez besoin de plus de temps ou si vous avez des difficultés à téléverser des fichiers, veuillez nous envoyer un message sécurisé et nous vous aiderons.\\n\\n[link url=\\\"{portal_dashboard_url}\\\"]Connectez-vous ici pour téléverser des documents ou envoyer un message[/link]\\n\\nSi nous n’avons pas de vos nouvelles, votre dossier pourrait être fermé.\\n\\nVotre équipe ISET au NWAC\\n\"}}','2026-01-16 12:31:53','2026-01-16 12:32:38');
/*!40000 ALTER TABLE `notification_template` ENABLE KEYS */;
UNLOCK TABLES;

