equiredMessage\": {\"en\": \"Select the country or territory you live in\"}}, \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-09-18 13:21:37','2025-09-18 13:21:37'),(1444,113,1,1,'{\"id\": \"example-radio\", \"hint\": {\"text\": {\"en\": \"You can only choose one\"}}, \"name\": \"example-radio\", \"items\": [{\"text\": \"Yes\", \"value\": \"true\"}, {\"text\": \"No\", \"value\": \"false\", \"conditionalChildId\": \"1442_false_follow\"}], \"classes\": \"govuk-radios\", \"disabled\": false, \"fieldset\": {\"legend\": {\"text\": \"Have you had a Canadian passport before?\", \"classes\": \"govuk-fieldset__legend--l\", \"isPageHeading\": false}}, \"formGroup\": {\"classes\": \"\"}, \"validation\": {\"rules\": [], \"required\": true, \"requiredMessage\": {\"en\": \"Please tell us if you\'ve had a passport before\"}}}','2025-09-18 13:28:21','2025-09-18 13:28:21'),(1445,113,2,22,'{\"id\": \"1442_false_follow\", \"html\": \"\", \"name\": \"1442_false_follow\", \"text\": \"This section contains important background information.\", \"label\": {\"text\": \"You may need an interview\"}, \"classes\": \"\", \"fieldset\": {\"legend\": {\"text\": \"You may need an interview\", \"classes\": \"\", \"isPageHeading\": false}}}','2025-09-18 13:28:21','2025-09-18 13:28:21'),(1454,116,1,30,'{\"id\": \"panel\", \"html\": \"\", \"name\": \"panel\", \"classes\": \"\", \"titleText\": \"You live in Canada!\", \"headingLevel\": 1}','2025-09-23 15:47:54','2025-09-23 15:47:54'),(1456,115,1,30,'{\"id\": \"panel\", \"html\": \"\", \"name\": \"panel\", \"classes\": \"\", \"titleText\": \"You don\'t live in Canada!\", \"headingLevel\": 1}','2025-09-23 15:51:26','2025-09-23 15:51:26'),(1458,118,1,31,'{\"id\": \"example-character-count\", \"hint\": {\"text\": {\"en\": \"Do not include personal information.\"}}, \"name\": \"example-character-count\", \"rows\": 5, \"label\": {\"text\": {\"en\": \"Describe your request\", \"fr\": \"Champ avec compteur de caractères\"}, \"classes\": \"govuk-label--m\"}