, \"components\": [{\"ref\": \"registration-number\", \"type\": \"input\", \"label\": \"registration-number\"}]}, {\"stepId\": 79, \"stepName\": \"Social Insurance Number\", \"components\": [{\"ref\": \"social-insurance-number\", \"type\": \"input\", \"label\": \"social-insurance-number\"}]}, {\"stepId\": 98, \"stepName\": \"Summary Page\", \"components\": [{\"ref\": \"text-block\", \"type\": \"text-block\", \"label\": \"text-block\"}, {\"ref\": \"text-block-2\", \"type\": \"text-block\", \"label\": \"text-block-2\"}, {\"ref\": \"summary-list\", \"type\": \"summary-list\", \"label\": \"summary-list\"}, {\"ref\": \"summary-list-2\", \"type\": \"summary-list\", \"label\": \"summary-list-2\"}, {\"ref\": \"summary-list-3\", \"type\": \"summary-list\", \"label\": \"summary-list-3\"}, {\"ref\": \"summary-list-4\", \"type\": \"summary-list\", \"label\": \"summary-list-4\"}, {\"ref\": \"summary-list-5\", \"type\": \"summary-list\", \"label\": \"summary-list-5\"}, {\"ref\": \"summary-list-6\", \"type\": \"summary-list\", \"label\": \"summary-list-6\"}, {\"ref\": \"summary-list-7\", \"type\": \"summary-list\", \"label\": \"summary-list-7\"}, {\"ref\": \"summary-list-8\", \"type\": \"summary-list\", \"label\": \"summary-list-8\"}, {\"ref\": \"summary-list-9\", \"type\": \"summary-list\", \"label\": \"summary-list-9\"}]}], \"conditionsWorkflowId\": 21}','2026-03-17 08:49:13','2026-03-17 08:49:13'),(4505,105,20,19,'{\"id\": \"uploaded-file-12\", \"hint\": {\"text\": {\"en\": \"Please attach a recent résumé (CV).\", \"fr\": \"Veuillez joindre un curriculum vitæ (CV) récent.\"}}, \"name\": \"uploaded-resume\", \"label\": {\"text\": {\"en\": \"Resume / CV\", \"fr\": \"Curriculum vitæ\"}, \"classes\": \"govuk-label--m\"}, \"accept\": \".pdf,.doc,.docx,.rtf,.txt,.jpg,.jpeg,.png\", \"classes\": \"\", \"disabled\": false, \"multiple\": true, \"formGroup\": {\"classes\": \"\"}, \"maxSizeMb\": 5, \"validation\": {\"rules\": [], \"required\": true, \"requiredMessage\": {\"en\": \"Please upload a current resume or CV.\", \"fr\": \"Veuillez téléverser un curriculum vitæ à jour.\"}}, \"showMaxSize\": true, \"documentType\": \"resume\", \"errorMessage\": {\"text\": {\"en\": \"\"}}, \"showMimeList\": false, \"documentLabel\": \"Resume / CV\"}','2026-03-17 08:49:13','2026-03-17 08:49:13'),(4511,77,1,29,'{\"id\": \"text-block\", \"html\": \"\", \"name\": \"text-block\", \"text\": {\"en\": \"Indigenous identity declaration\", \"fr\": \"Déclaration d’identité autochtone\"}, \"classes\": \"govuk-heading-l\"}','2026-03-24 10:51:52','2026-03-24 10:51:52'),(4512,77,2,29,'{\"id\": \"text-block-2\", \"html\": \"\", \"name\": \"text-block-2\", \"text\": {\"en\": \"I understand that the Indigenous Skills and Employment Training (ISET) program helps increase Indigenous participation in the Canadian labour market and supports access to meaningful, sustainable employment. The program provides training and employment supports to Indigenous women in all their gender diversity in Canada, including First Nations applicants with or without status, Inuit applicants, and Métis applicants living on reserve, off reserve, in urban centres, or in rural or remote communities.\", \"fr\": \"Je comprends que le programme de formation et d’emploi des compétences des Autochtones (ISET) contribue à accroître la participation des Autochtones au marché du travail canadien et à soutenir l’accès à un emploi significatif et durable. Le programme offre des soutiens à la formation et à l’emploi aux femmes autochtones dans toute leur diversité de genre au Canada, y compris aux membres des Premières Nations avec ou sans statut, aux Inuit et aux Métis vivant dans une réserve, hors réserve, dans un centre urbain ou dans une communauté rurale ou éloignée.\"}, \"classes\": \"govuk-body\"}','2026-03-24 10:51:52','2026-03-24 10:51:52'),(4513,77,3,29,'{\"id\": \"text-block-3\", \"html\": \"\", \"name\": \"text-block-3\", \"text\": {\"en\": \"I understand that NWAC may review my eligibility if information about my Indigenous identity is incomplete, false, or misleading. If a review confirms that I was not eligible, funding may be paused or ended, any funding agreement may be cancelled, and ineligible funds may need to be repaid to ESDC.\", \"fr\": \"Je comprends que l’AFAC peut revoir mon admissibilité si les renseignements fournis au sujet de mon identité autochtone sont incomplets, faux ou trompeurs. Si une vérification confirme que je n’étais pas admissible, le financement peut être suspendu ou prendre fin, toute entente de financement peut être annulée et les fonds non admissibles peuvent devoir être remboursés à EDSC.\"}, \"classes\": \"govuk-body\"}','2026-03-24 10:51:52','2026-03-24 10:51:52'),(4514,77,4,26,'{\"id\": \"example-input\", \"hint\": {\"text\": {\"en\": \"For example: Mohawks of Kahnawà:ke; Inuit of Nunatsiavut; Métis Nation of Alberta, Region 3.\", \"fr\": \"Par exemple : Mohawks de Kahnawà:ke; Inuit du Nunatsiavut; Nation métisse de l’Alberta, région 3.\"}}, \"mask\": \"\", \"name\": \"indigenous-affiliation-declaration\", \"type\": \"text\", \"label\": {\"text\": {\"en\": \"My Nation, community, or treaty area\", \"fr\": \"Ma Nation, ma communauté ou mon territoire visé par un traité\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"\", \"spellcheck\": true, \"validation\": {\"rules\": [], \"required\": true, \"requiredMessage\": {\"en\": \"Please tell us your Nation, community, or treaty area.\", \"fr\": \"Veuillez indiquer votre Nation, votre communauté ou votre territoire visé par un traité.\"}}, \"autocomplete\": \"\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2026-03-24 10:51:52','2026-03-24 10:51:52'),(4515,77,5,35,'{\"id\": \"applicant_signature\", \"hint\": {\"text\": {\"en\": \"I declare that I identify as an Indigenous person in Canada. For this program, Indigenous means First Nations, Inuit, or Métis.\", \"fr\": \"Je déclare que je m’identifie comme une personne autochtone au Canada. Pour ce programme, cela signifie être membre des Premières Nations, Inuit ou Métis.\"}}, \"name\": \"indigenous_declaration\", \"label\": {\"text\": {\"en\": \"Type your full name to sign this declaration\", \"fr\": \"Tapez votre nom complet pour signer cette déclaration\"}, \"classes\": \"govuk-label--m\"}, \"required\": true, \"formGroup\": {\"classes\": \"\"}, \"boxPadding\": \"m\", \"clearLabel\": {\"text\": {\"en\": \"Clear\", \"fr\": \"Effacer\"}}, \"actionLabel\": {\"text\": {\"en\": \"Sign Now\", \"fr\": \"Signer maintenant\"}}, \"placeholder\": {\"text\": {\"en\": \"First name Last name\", \"fr\": \"Prénom Nom de famille\"}}, \"handwritingFont\": \"cursive\", \"statusSignedText\": {\"text\": {\"en\": \"Signed\", \"fr\": \"Signé\"}}, \"statusUnsignedText\": {\"text\": {\"en\": \"Not signed\", \"fr\": \"Non signé\"}}}','2026-03-24 10:51:52','2026-03-24 10:51:52'),(4526,126,1,29,'{\"id\": \"text-block\", \"html\": \"\", \"name\": \"text-block\", \"text\": {\"en\": \"Conflict of interest declaration\", \"fr\": \"Déclaration de conflit d’intérêts\"}, \"classes\": \"govuk-heading-l\"}','2026-03-24 10:55:47','2026-03-24 10:55:47'),(4527,126,2,29,'{\"id\": \"text-block-2\", \"html\": \"\", \"name\": \"text-block-2\", \"text\": {\"en\": \"The Indigenous Skills and Employment Training (ISET) program is committed to fair, transparent, and accountable funding decisions.\", \"fr\": \"Le programme de formation en compétences et emploi autochtones (PFCEA) s\'engage à prendre des décisions de financement justes, transparentes et responsables.\"}, \"classes\": \"govuk-body\"}','2026-03-24 10:55:47','2026-03-24 10:55:47'),(4528,126,3,29,'{\"id\": \"text-block-3\", \"html\": \"\", \"name\": \"text-block-3\", \"text\": {\"en\": \"To support fairness, please tell us about any actual, potential, or perceived conflict of interest related to your application.\", \"fr\": \"Pour soutenir l’équité, veuillez nous informer de tout conflit d’intérêts réel, potentiel ou perçu lié à votre demande.\"}, \"classes\": \"govuk-body\"}','2026-03-24 10:55:47','2026-03-24 10:55:47'),(4529,126,4,29,'{\"id\": \"text-block-4\", \"html\": \"\", \"name\": \"text-block-4\", \"text\": {\"en\": \"1. I am not aware of any personal, family, financial, or other relationship with NWAC staff or regional member-association staff that could influence, or appear to influence, the review of my ISET application.\", \"fr\": \"1. À ma connaissance, je n’ai aucune relation personnelle, familiale, financière ou autre avec un membre du personnel de l’AFAC ou d’une association membre régionale qui pourrait influencer, ou sembler influencer, l’examen de ma demande ISET.\"}, \"classes\": \"govuk-body\"}','2026-03-24 10:55:47','2026-03-24 10:55:47'),(4530,126,5,29,'{\"id\": \"text-block-5\", \"html\": \"\", \"name\": \"text-block-5\", \"text\": {\"en\": \"2. I have not tried to influence or pressure anyone involved in reviewing my ISET application.\", \"fr\": \"2. Je n’ai pas tenté d’influencer ni d’exercer de pression sur quiconque participe à l’examen de ma demande ISET.\"}, \"classes\": \"govuk-body\"}','2026-03-24 10:55:47','2026-03-24 10:55:47'),(4531,126,6,29,'{\"id\": \"text-block-6\", \"html\": \"\", \"name\": \"text-block-6\", \"text\": {\"en\": \"3. I understand that applications are reviewed according to program processes, and I have not asked for my application to be prioritized ahead of others.\", \"fr\": \"3. Je comprends que les demandes sont examinées selon les processus du programme et je n’ai pas demandé que ma demande soit priorisée avant celles des autres.\"}, \"classes\": \"govuk-body\"}','2026-03-24 10:55:47','2026-03-24 10:55:47'),(4532,126,7,29,'{\"id\": \"text-block-7\", \"html\": \"\", \"name\": \"text-block-7\", \"text\": {\"en\": \"4. If there is any actual, potential, or perceived conflict of interest or bias, I have described it below.\", \"fr\": \"4. S’il existe un conflit d’intérêts ou un biais réel, potentiel ou perçu, je l’ai décrit ci-dessous.\"}, \"classes\": \"govuk-body\"}','2026-03-24 10:55:47','2026-03-24 10:55:47'),(4533,126,8,1,'{\"id\": \"example-radio\", \"hint\": {\"text\": {\"en\": \"Please select the option that applies to you.\", \"fr\": \"Veuillez sélectionner l’option qui s’applique à vous.\"}}, \"name\": \"conflict_of_interest\", \"items\": [{\"hint\": \"\", \"text\": {\"en\": \"I have no conflict of interest or bias to declare\", \"fr\": \"Je n’ai aucun conflit d’intérêts ni biais à déclarer\"}, \"value\": \"no_conflict\"}, {\"text\": {\"en\": \"I want to declare a possible conflict of interest or bias\", \"fr\": \"Je souhaite déclarer un conflit d’intérêts ou un biais possible\"}, \"value\": \"conflict\", \"conditionalChildId\": \"2022_conflict_follow\"}], \"classes\": \"govuk-radios\", \"disabled\": false, \"fieldset\": {\"legend\": {\"text\": {\"en\": \"I confirm that one of the following applies:\", \"fr\": \"Je confirme qu’une des situations suivantes s’applique :\"}, \"classes\": \"govuk-fieldset__legend--s\", \"isPageHeading\": false}}, \"formGroup\": {\"classes\": \"\"}, \"validation\": {\"rules\": [], \"required\": true, \"requiredMessage\": {\"en\": \"Please tell us whether you have a conflict of interest to declare.\", \"fr\": \"Veuillez indiquer si vous avez un conflit d’intérêts à déclarer.\"}}}','2026-03-24 10:55:47','2026-03-24 10:55:47'),(4534,126,9,32,'{\"id\": \"2022_conflict_follow\", \"hint\": {\"text\": {\"en\": \"Share only the information needed to explain the situation.\", \"fr\": \"Indiquez seulement les renseignements nécessaires pour expliquer la situation.\"}}, \"name\": \"2022_conflict_follow\", \"rows\": 3, \"label\": {\"text\": {\"en\": \"Please describe the possible conflict of interest or bias\", \"fr\": \"Veuillez décrire le conflit d’intérêts ou le biais possible\"}, \"classes\": \"govuk-label--m\"}, \"value\": \"\", \"classes\": \"govuk-textarea\", \"fieldset\": {\"legend\": {\"text\": {\"en\": \"Please describe the possible conflict of interest or bias\", \"fr\": \"Veuillez décrire le conflit d’intérêts ou le biais possible\"}, \"classes\": \"\", \"isPageHeading\": false}}, \"formGroup\": {\"classes\": \"\"}, \"spellcheck\": true, \"validation\": {\"rules\": [], \"required\": true, \"requiredMessage\": {\"en\": \"Please describe the possible conflict of interest or bias.\", \"fr\": \"Veuillez décrire le conflit d’intérêts ou le biais possible.\"}}, \"autocomplete\": \"\", \"errorMessage\": {\"text\": \"\"}}','2026-03-24 10:55:47','2026-03-24 10:55:47'),(4535,126,10,35,'{\"id\": \"applicant_signature\", \"hint\": {\"text\": {\"en\": \"Type your full legal name and select Sign.\", \"fr\": \"Tapez votre nom légal complet, puis sélectionnez Signer.\"}}, \"name\": \"conflict_applicant_signature\", \"label\": {\"text\": {\"en\": \"Type your full name to sign\", \"fr\": \"Tapez votre nom complet pour signer\"}, \"classes\": \"govuk-label--m\"}, \"required\": true, \"formGroup\": {\"classes\": \"\"}, \"boxPadding\": \"m\", \"clearLabel\": {\"text\": {\"en\": \"Clear\", \"fr\": \"Effacer\"}}, \"actionLabel\": {\"text\": {\"en\": \"Sign now\", \"fr\": \"Signer maintenant\"}}, \"placeholder\": {\"text\": {\"en\": \"First name Last name\", \"fr\": \"Prénom Nom de famille\"}}, \"handwritingFont\": \"cursive\", \"statusSignedText\": {\"text\": {\"en\": \"Signed\", \"fr\": \"Signé\"}}, \"statusUnsignedText\": {\"text\": {\"en\": \"Unsigned\", \"fr\": \"Non signé\"}}}','2026-03-24 10:55:47','2026-03-24 10:55:47');
