CREATE DEFINER=`root`@`localhost` PROCEDURE `CheckInUser`(
    IN p_booking_id INT,
    IN p_slot_id INT,
    IN p_location_id INT,
    IN p_ticket_number VARCHAR(10)
)
BEGIN
    INSERT INTO queue (
        booking_id,
        slot_id,
        location_id,
        ticket_number,
        status,
        check_in_time
    )
    VALUES (
        p_booking_id,
        p_slot_id,
        p_location_id,
        p_ticket_number,
        'waiting',
        NOW()
    );
END ;;
